$(document).ready(function() {

    $('#dismiss, .overlay').on('click', function() {
        $('#sidebar').removeClass('active');
        $('.overlay').removeClass('active');
    });

    $('#sidebarCollapse').on('click', function() {
        
        $('#sidebar').addClass('active');
        $('.overlay').addClass('active');

        $(this).toggleClass('in');
        $('a[aria-expanded=true]').attr('aria-expanded', 'false');
    }); 

    var options = {
        onKeyPress : function(cpfcnpj, e, field, options) {
           var masks = ['000.000.000-000', '00.000.000/0000-00'];
           var mask = (cpfcnpj.length > 14) ? masks[1] : masks[0];
           $('#cpf').mask(mask, options);
        }
    };

    var $cpf = $('#cpf').val();

    if($cpf != undefined){
        if($cpf.length >= 14){
            $('#cpf').mask('00.000.000/0000-00', options);
        }
        else{
            $('#cpf').mask('000.000.000-00', options);
        }
    }

    $("#data_nascimento").mask("00/00/0000");
    $("#celular").mask("(00) 00000-0000");

});

$("#categoria_assunto").change(function () {

    if( $(this).val() ) {
        var id_categoria = $(this).val();
        _token = $('input[name="_token"]').val();
        $.ajax({
            type: "POST",
            url: '/assuntos/retornaAssuntos',
            dataType: 'JSON',
            data: {_token : _token, id_categoria:id_categoria},
            timeout: 5000,
            beforeSend: function(){
                $(".loader").show();
            },
            complete:function(data){
                $(".loader").delay(600).fadeOut("slow");
            },
            success: function(data) {
                $('#assunto').empty()
                $.each(data, function (key, value) {
                    $('#assunto').append('<option value=' + key + '>' + value + '</option>');
                });
            },
            error: function(data){
                var errors = data.responseJSON;

                if(data.statusText == "timeout"){
                    $("#error-message").html("Erro ao pesquisar assuntos. Por favor, atualize a página e tente novamente.");
                }
                else{
                    if(errors.hasOwnProperty('error')){
                        $("#error-message").html(errors.error);
                    }
                    else{
                        $("#error-message").html(data.responseJSON);
                    }
                }

                $('#ModalError').modal('show');
            }
        });

    } else {
        $('#assunto').html('<option value="">Selecione um assunto</option>');
    }

});







